#include <iostream>

// Node structure
struct Node {
    int data;
    Node* next;
};

// Function to separate even and odd nodes
Node* separate(Node* head) {
    // Even list
    Node* evenHead = nullptr;
    Node* evenTail = nullptr;

    // Odd list
    Node* oddHead = nullptr;
    Node* oddTail = nullptr;

    // Traverse the linked list
    while (head != nullptr) {
        // If the current node is even
        if (head->data % 2 == 0) {
            // Add to even list
            if (evenHead == nullptr) {
                evenHead = head;
                evenTail = head;
            } else {
                evenTail->next = head;
                evenTail = evenTail->next;
            }
        } else {
            // Add to odd list
            if (oddHead == nullptr) {
                oddHead = head;
                oddTail = head;
            } else {
                oddTail->next = head;
                oddTail = oddTail->next;
            }
        }
        // Move to next node
        Node* temp = head;
        head = head->next;
        delete temp;
    }

    // If there are no even nodes, return the original list
    if (evenHead == nullptr) {
        return oddHead;
    }

    // Merge even and odd lists
    evenTail->next = oddHead;
    return evenHead;
}

// Function to print the linked list
void print(Node* head) {
    while (head != nullptr) {
        std::cout << head->data << " ";
        head = head->next;
    }
    std::cout << std::endl;
}

int main() {
    // Create a sample linked list
    Node* head = new Node(0);
    head->next = new Node(1);
    head->next->next = new Node(4);
    head->next->next->next = new Node(6);
    head->next->next->next->next = new Node(9);
    head->next->next->next->next->next = new Node(10);
    head->next->next->next->next->next->next = new Node(11);

    // Print the original linked list
    std::cout << "Original Linked List: ";
    print(head);

    // Separate even and odd nodes
    head = separate(head);

    // Print the modified linked list
    std::cout << "Modified Linked List: ";
    print(head);

    return 0;
}
